function initializeOperationTiles() {
  Object.entries(operationTileConfigs).forEach(([viewId, operations]) => {
    const section = document.getElementById(viewId);
    if (!section || section.querySelector(".operation-tile-grid")) return;
    const tileGrid = document.createElement("div");
    tileGrid.className = `tile-grid operation-tile-grid ${viewId}-operation-tiles`;
    tileGrid.innerHTML = operations.map((operation) => `
      <button class="action-tile${operation.ownerOnly ? " owner-only" : ""}" type="button" data-operation-view="${escapeHtml(viewId)}" data-operation-page="${escapeHtml(operation.id)}">
        <strong>${escapeHtml(operation.title)}</strong>
        <span>${escapeHtml(operation.description)}</span>
      </button>
    `).join("");
    const dashboard = section.querySelector(".operation-dashboard");
    section.insertBefore(tileGrid, dashboard ? dashboard.nextSibling : section.firstElementChild);
    operations.forEach((operation) => {
      const target = section.querySelector(operation.selector);
      if (!target) return;
      target.classList.add("operation-page");
      target.dataset.operationPage = operation.id;
    });
  });
  document.querySelectorAll("[data-operation-view][data-operation-page]").forEach((button) => {
    button.addEventListener("click", () => openOperationPage(button.dataset.operationView, button.dataset.operationPage));
  });
}

function openOperationPage(viewId, pageId) {
  if (viewId === "transfer-history") {
    openTransferHistoryOperationDialog(pageId);
    return;
  }
  const section = document.getElementById(viewId);
  if (!section) return;
  section.classList.add("operation-open");
  section.querySelectorAll("[data-operation-view]").forEach((button) => {
    button.classList.toggle("active", button.dataset.operationPage === pageId);
  });
  section.querySelectorAll(".operation-page").forEach((page) => {
    const isActivePage = page.dataset.operationPage === pageId;
    page.classList.toggle("active-operation-page", isActivePage);
    page.hidden = !isActivePage;
  });
  refreshOperationPage(viewId, pageId);
}

function refreshOperationPage(viewId, pageId) {
  if (viewId === "melting") renderMelting();
  if (viewId === "safe") renderSafe();
  if (viewId === "factory") renderFactory();
  if (viewId === "customers" && pageId === "master") renderCustomers();
  if (viewId === "karigars" && pageId === "master") renderKarigars();
  if (viewId === "billing" && pageId === "bill") renderBills();
  if (viewId === "transfer-history" && pageId === "history") renderOnlineTransferHistory();
  if (viewId === "transfer-history" && pageId === "department") renderDepartmentTransferHistoryBoard();
  if (viewId === "reports" && pageId === "summary") renderReports();
  if (viewId === "users" && pageId === "login") renderLoginUsers();
}

function captureDeleteRefreshContext(overrides = {}) {
  const orderDialog = document.getElementById("order-dialog");
  const historyDialog = document.getElementById("history-dialog");
  const designCategoryDialog = document.getElementById("design-category-dialog");
  const officeDialog = document.getElementById("office-details-dialog");
  const safeHistoryDialog = document.getElementById("safe-item-issue-history-dialog");
  const meltingViewDialog = document.getElementById("melting-view-dialog");
  const operationPages = Array.from(document.querySelectorAll(".view.operation-open")).map((section) => ({
    viewId: section.id,
    pageId: section.querySelector(".operation-page.active-operation-page")?.dataset.operationPage
      || section.querySelector("[data-operation-view].active")?.dataset.operationPage
      || "",
  })).filter((entry) => entry.viewId && entry.pageId);
  return {
    operationPages,
    orderDialogOpen: Boolean(orderDialog?.open),
    orderId: overrides.orderId || orderDialog?.dataset.orderId || document.querySelector('#update-order-form [name="orderId"]')?.value || "",
    orderBucket: orderDialog?.dataset.bucket || "all",
    orderEditMode: !document.getElementById("update-order-form")?.classList.contains("hidden"),
    historyDialogOpen: Boolean(historyDialog?.open),
    lotId: overrides.lotId || historyDialog?.dataset.lotId || "",
    designCategoryOpen: Boolean(designCategoryDialog?.open),
    designCategory: document.getElementById("design-category-title")?.textContent || "",
    officeDialogOpen: Boolean(officeDialog?.open),
    officePage: officeDialog?.dataset.page || "",
    officeItemKey: officeDialog?.dataset.officeItemKey || "",
    safeHistoryOpen: Boolean(safeHistoryDialog?.open),
    safeItemId: safeHistoryDialog?.dataset.safeItemId || "",
    meltingViewOpen: Boolean(meltingViewDialog?.open),
    meltingId: meltingViewDialog?.dataset.meltingId || "",
    dailyContainerOpen: Boolean(document.getElementById("daily-tally-container-dialog")?.open),
  };
}

function refreshAfterDelete(overrides = {}) {
  const context = captureDeleteRefreshContext(overrides);
  render();
  context.operationPages.forEach(({ viewId, pageId }) => {
    if (viewId === "transfer-history") openTransferHistoryOperationDialog(pageId);
    else openOperationPage(viewId, pageId);
  });
  if (context.designCategoryOpen) {
    const categoryExists = designCategoryGroups().some((group) => group.category === context.designCategory);
    if (categoryExists) openDesignCategory(encodeURIComponent(context.designCategory));
    else document.getElementById("design-category-dialog")?.close();
  }
  if (context.orderDialogOpen) {
    const order = findById("orders", context.orderId);
    if (order) openOrderDetail(order.id, context.orderEditMode, context.orderBucket);
    else document.getElementById("order-dialog")?.close();
  }
  if (context.historyDialogOpen) {
    if (findById("lots", context.lotId)) openLotHistory(context.lotId);
    else document.getElementById("history-dialog")?.close();
  }
  if (context.safeHistoryOpen) {
    if (findById("safeItems", context.safeItemId)) openSafeItemIssueHistory(context.safeItemId);
    else document.getElementById("safe-item-issue-history-dialog")?.close();
  }
  if (context.meltingViewOpen) {
    if (findById("melting", context.meltingId)) openMeltingView(context.meltingId);
    else document.getElementById("melting-view-dialog")?.close();
  }
  if (context.officeDialogOpen && context.officePage) {
    if (context.officePage === "product-view" && context.officeItemKey && findOfficeBillItem(context.officeItemKey)) {
      openOfficeItemView(context.officeItemKey);
    } else if (context.officePage === "product-view") {
      openOfficeDialogPage(document.getElementById("office-details-dialog")?.dataset.backPage || "all");
    } else {
      openOfficeDialogPage(context.officePage);
    }
  }
  if (context.dailyContainerOpen) renderDailyTallyContainers();
  refreshOpenDepartmentTransferHistory();
}

function saveDeletionAndRefresh(overrides = {}) {
  saveState();
  refreshAfterDelete(overrides);
}

function resetOperationPage(viewId) {
  const section = document.getElementById(viewId);
  if (!section || !operationTileConfigs[viewId]) return;
  section.classList.remove("operation-open");
  section.querySelectorAll("[data-operation-view]").forEach((button) => button.classList.remove("active"));
  section.querySelectorAll(".operation-page").forEach((page) => {
    page.classList.remove("active-operation-page");
    page.hidden = true;
  });
  if (viewId === "transfer-history") closeTransferHistoryOperationDialog();
}

function openTransferHistoryOperationDialog(pageId) {
  const operation = (operationTileConfigs["transfer-history"] || []).find((item) => item.id === pageId);
  if (!operation) return;
  const onlineDialog = document.getElementById("online-transfer-history-dialog");
  const departmentDialog = document.getElementById("department-transfer-history-dialog");
  if (pageId === "history" && !onlineDialog) return;
  if (pageId === "department" && !departmentDialog) return;
  if (pageId === "history" && departmentDialog?.open) departmentDialog.close();
  if (pageId === "department" && onlineDialog?.open) onlineDialog.close();
  const section = document.getElementById("transfer-history");
  const dialog = pageId === "history" ? onlineDialog : departmentDialog;
  dialog.dataset.activePage = pageId;
  section?.classList.add("operation-open");
  section?.querySelectorAll("[data-operation-view='transfer-history']").forEach((button) => {
    button.classList.toggle("active", button.dataset.operationPage === pageId);
  });
  refreshOperationPage("transfer-history", pageId);
  if (!dialog.open) dialog.showModal();
}

function clearTransferHistoryOperationState() {
  const onlineDialog = document.getElementById("online-transfer-history-dialog");
  const departmentDialog = document.getElementById("department-transfer-history-dialog");
  if (onlineDialog?.open || departmentDialog?.open) return;
  const section = document.getElementById("transfer-history");
  section?.classList.remove("operation-open");
  section?.querySelectorAll("[data-operation-view='transfer-history']").forEach((button) => button.classList.remove("active"));
  if (onlineDialog) delete onlineDialog.dataset.activePage;
  if (departmentDialog) delete departmentDialog.dataset.activePage;
}

function closeTransferHistoryOperationDialog() {
  const onlineDialog = document.getElementById("online-transfer-history-dialog");
  const departmentDialog = document.getElementById("department-transfer-history-dialog");
  if (onlineDialog?.open) onlineDialog.close();
  if (departmentDialog?.open) departmentDialog.close();
  clearTransferHistoryOperationState();
}

