document.getElementById("order-form").addEventListener("submit", (event) => {
  event.preventDefault();
  if (!validateOrderDueDate(event.target)) return;
  const data = getFormData(event.target);
  const customer = findById("customers", data.customerId);
  if (!customer) {
    alert("Add or select a customer first.");
    return;
  }
  const items = getOrderFormItems(event.target);
  if (!items.length) {
    alert("Press Add Item first. Only added items will be saved in the job card.");
    return;
  }
  const jobNumber = `JOB-${state.nextOrder}`;
  const jobCardColor = data.jobColor || "Pink";
  const createdOrders = [];
  items.forEach((item) => {
    const productionNo = `PR-${state.nextOrder++}`;
    const orderRecord = {
      id: crypto.randomUUID(),
      number: productionNo,
      jobNumber,
      productionNo,
      barcode: productionNo,
      customerId: customer.id,
      customer: customer.name,
      designId: item.designId,
      designNumber: designLabel(item.designId),
      category: item.category,
      item: item.item || designLabel(item.designId) || item.category || item.remarks,
      size: item.size,
      ringType: item.ringType,
      cmItemType: item.cmItemType,
      clSize: item.clSize,
      cgSize: item.cgSize,
      color: jobCardColor,
      purity: item.purity,
      itemPcs: 1,
      orderedPcs: Number(item.orderedPcs || 1),
      pieceIndex: Number(item.pieceIndex || 1),
      targetWeight: 0,
      remarks: item.remarks,
      orderDate: data.orderDate,
      productionDays: Number(data.productionDays),
      dueDate: data.dueDate,
      urgent: data.urgent === "on",
      status: "Pending",
      createdAt: new Date().toISOString(),
    };
    orderRecord.productionStoneItems = buildProductionStoneItemsForOrder(orderRecord);
    state.orders.push(orderRecord);
    createdOrders.push(orderRecord);
  });
  backupRecentJobOrders(createdOrders);
  event.target.reset();
  clearOrderDraft();
  setDefaultOrderDates(event.target);
  resetOrderItemRows();
  saveState();
  render();
  switchOrderPage("active");
});

document.getElementById("design-form").addEventListener("submit", async (event) => {
  event.preventDefault();
  if (!requirePageEditPermission("designs", "upload or update designs")) return;
  const form = event.target;
  const data = getFormData(form);
  const selectedCategory = normalizeDesignCategory(data.category);
  const selectedItemKeys = normalizeDesignItemKeys(data.itemKeys, selectedCategory);
  const existing = data.designId ? findById("designs", data.designId) : null;
  const imageFiles = [...form.image.files];
  const stoneChartFiles = [...form.stoneChart.files];
  const uploadGroups = groupDesignUploadFiles(imageFiles);
  const status = document.getElementById("design-upload-status");
  const submitButton = document.getElementById("design-submit");
  if (!existing && imageFiles.length > 500) {
    alert("Please select maximum 500 design images at one time.");
    return;
  }
  if (!selectedCategory) {
    alert("Please select or enter category before uploading design images.");
    form.category?.focus();
    return;
  }
  form.category.value = selectedCategory;
  if (form.itemKeys) form.itemKeys.value = designItemKeysText(selectedItemKeys);
  submitButton.disabled = true;
  const previousDesigns = [...state.designs];
  const uploadCropPermission = createStoneCropUploadPermission();
  const uploadFailures = [];
  try {
    if (existing) {
      const group = uploadGroups.find((item) => designMatchKeys(existing).includes(item.key)) || uploadGroups[0];
      const imageFile = group?.designFile || imageFiles[0];
      const designName = group?.designName || designNameFromFile(imageFile?.name) || existing.number;
      const smartImageResult = imageFile && !isStoneChartUploadFile(imageFile.name)
        ? await saveDesignUploadImageAndAutoChart(existing, imageFile, { saveDesign: true, cropPermission: uploadCropPermission })
        : { chartAttached: false };
      const chartCandidates = [...(group?.chartFiles || []), ...stoneChartFiles];
      const matchingStoneChartFile = matchingStoneChartFileForDesign(chartCandidates, existing) || (stoneChartFiles.length === 1 ? stoneChartFiles[0] : null) || group?.chartFiles?.[0] || null;
      const matchingStoneChartResult = matchingStoneChartFile
        ? await saveStoneChartFileForDesign(existing, matchingStoneChartFile)
        : { itemSaved: false, sourceSaved: false };
      const design = {
        id: existing.id,
        number: data.number || designName,
        name: data.name || data.number || designName,
        category: selectedCategory,
        itemKeys: selectedItemKeys,
        stoneDetails: existing.stoneDetails || "",
        stoneItems: existing.stoneItems || [],
        stoneChartItems: existing.stoneChartItems || [],
        hasStoneChartSource: existing.hasStoneChartSource || matchingStoneChartResult.sourceSaved,
        stoneChartSourceName: existing.stoneChartSourceName || matchingStoneChartFile?.name || "",
        hasStoneChart: existing.hasStoneChart || matchingStoneChartResult.itemSaved || smartImageResult.chartAttached,
      };
      Object.assign(existing, design);
      updateDesignReferences(existing);
    } else {
      if (!imageFiles.length) {
        alert("Select one or more design images.");
        return;
      }
      let createdCount = 0;
      let updatedCount = 0;
      let matchedStoneCharts = 0;
      const duplicateGroups = [];
      for (const [index, group] of uploadGroups.entries()) {
        const designName = group.designName || designNameFromFile(group.designFile?.name) || `Design ${index + 1}`;
        status.textContent = `Uploading ${index + 1} of ${uploadGroups.length}: ${designName}`;
        const duplicateDesign = findDesignByUploadKey(group.key);
        if (duplicateDesign) {
          duplicateGroups.push({ group, existingDesign: duplicateDesign });
          continue;
        }
        const design = createDesignFromUploadGroup(group, selectedCategory, "", selectedItemKeys);
        try {
          let chartAttachedForDesign = 0;
          if (group.designFile) {
            const smartImageResult = await saveDesignUploadImageAndAutoChart(design, group.designFile, { saveDesign: true, cropPermission: uploadCropPermission });
            chartAttachedForDesign = smartImageResult.chartAttached ? 1 : 0;
          }
          const chartCandidates = [...group.chartFiles, ...stoneChartFiles];
          const matchingStoneChartFile = matchingStoneChartFileForDesign(chartCandidates, design)
            || group.chartFiles[0]
            || (stoneChartFiles.length === 1 && uploadGroups.length === 1 ? stoneChartFiles[0] : null);
          if (matchingStoneChartFile) {
            const matchingStoneChartResult = await saveStoneChartFileForDesign(design, matchingStoneChartFile);
            chartAttachedForDesign = matchingStoneChartResult.sourceSaved || matchingStoneChartResult.itemSaved ? 1 : chartAttachedForDesign;
          }
          state.designs.push(design);
          createdCount += 1;
          matchedStoneCharts += chartAttachedForDesign;
        } catch (error) {
          console.warn("Design upload failed", designName, error);
          uploadFailures.push(`${designName}: ${uploadErrorText(error)}`);
          await deleteDesignImage(design.id).catch(() => {});
          await deleteAllStoneChartImages(design).catch(() => {});
        }
      }
      if (duplicateGroups.length) {
        const duplicateActions = await chooseDuplicateDesignUploadAction(duplicateGroups);
        const totalDuplicates = duplicateGroups.length;
        let duplicateDone = 0;
        let duplicateFailed = 0;
        status.textContent = `Applying duplicate action(s): ${summarizeDuplicateDesignActions(duplicateActions)}. Starting 0 of ${totalDuplicates}.`;
        await waitForUiPaint();
        for (const [index, { group, existingDesign }] of duplicateGroups.entries()) {
          const duplicateAction = duplicateActions[index] || "SKIP";
          const designName = group?.designName || designText(existingDesign) || `Duplicate ${index + 1}`;
          status.textContent = `${duplicateActionProgressText(duplicateAction)} ${index + 1} of ${totalDuplicates}: ${designName}`;
          await waitForUiPaint();
          try {
            const result = await resolveDuplicateDesignUpload(group, existingDesign, selectedCategory, stoneChartFiles, { cropPermission: uploadCropPermission, duplicateAction, itemKeys: selectedItemKeys });
            updatedCount += result.updated;
            createdCount += result.created;
            matchedStoneCharts += result.chartAttached;
            duplicateDone += 1;
            status.textContent = `Duplicate progress: ${duplicateDone} of ${totalDuplicates} done, ${duplicateFailed} failed. Latest: ${duplicateActionProgressDoneText(duplicateAction)} ${designName}.`;
            if (duplicateDone % 5 === 0 || duplicateDone === totalDuplicates) saveStateLocalOnly();
          } catch (error) {
            duplicateFailed += 1;
            console.warn("Duplicate design upload failed", designName, error);
            uploadFailures.push(`${designName}: ${uploadErrorText(error)}`);
            status.textContent = `Duplicate progress: ${duplicateDone} of ${totalDuplicates} done, ${duplicateFailed} failed. Failed: ${designName}.`;
          }
          await waitForUiPaint();
        }
      }
      const mergedImageCount = imageFiles.length - uploadGroups.length;
      const failureSummary = uploadFailures.length
        ? ` ${uploadFailures.length} failed: ${uploadFailures.slice(0, 5).join("; ")}${uploadFailures.length > 5 ? "; more failed files not shown" : ""}.`
        : "";
      status.dataset.uploadSummary = `${createdCount} design(s) created, ${updatedCount} existing/duplicate design(s) handled. ${mergedImageCount} extra image(s) merged into matching designs. ${matchedStoneCharts} stone chart(s) attached.${failureSummary}`;
    }
    form.reset();
    resetDesignForm();
    saveState();
    render();
    showDesignCategoryInMaster(selectedCategory);
    const uploadResultText = existing
      ? "Design updated. Matching design/chart images were merged."
      : status.dataset.uploadSummary || `${imageFiles.length} design image(s) uploaded. Matching stone sheet names were assigned automatically.`;
    const pendingCloudText = designImageUnsyncedIds.size
      ? ` ${designImageUnsyncedIds.size} image file(s) are saved in this browser but still waiting for cloud sync. Use Repair / Sync Images in Design Master.`
      : " Images are saved in Supabase for other laptops.";
    status.textContent = `${uploadResultText}${pendingCloudText}`;
    if (uploadFailures.length) {
      alert(`Upload finished with ${uploadFailures.length} failed image(s).\n\n${uploadFailures.slice(0, 8).join("\n")}${uploadFailures.length > 8 ? "\nMore failed files not shown." : ""}`);
    }
    delete status.dataset.uploadSummary;
  } catch (error) {
    state.designs = previousDesigns;
    const message = uploadErrorText(error);
    alert(`Upload could not be saved.\n\nReason: ${message}\n\nTry fewer images or smaller image files.`);
    status.textContent = `Upload could not be saved: ${message}`;
  } finally {
    submitButton.disabled = false;
  }
});

