document.getElementById("safe-issue-form").addEventListener("submit", (event) => {
  event.preventDefault();
  const form = event.target;
  const item = findById("safeItems", form.itemId.value);
  const destinationMode = normalizeSafeIssueDestinationMode(form.destinationMode.value);
  const linksJobCard = safeIssueLinksJobCard(destinationMode);
  const selection = linksJobCard ? safeIssueJobSelection(form.lotId.value) : safeIssueJobSelection();
  let lot = selection.lot;
  if (linksJobCard && !selection.jobNumber) {
    alert("Select one Job Card currently in production for this non-gold issue.");
    return;
  }
  const linkedOrder = linksJobCard && form.orderId?.value ? findById("orders", form.orderId.value) : null;
  if (form.orderId?.value && (!linkedOrder || !selection.orders.some((order) => order.id === linkedOrder.id))) {
    alert("Select a semi-finished product that belongs to this Job Card.");
    return;
  }
  if (destinationMode === "job") applySafeIssueLotDefaults(selection.value, Boolean(lot));
  const department = findById("karigars", form.departmentId.value);
  if (!item || item.status === "Out") {
    alert("This shelf item is no longer available.");
    document.getElementById("safe-issue-dialog").close();
    return;
  }
  if (!department) {
    alert(linksJobCard ? "The selected Job Card needs a current department before this item can be issued." : "Select department.");
    return;
  }
  const availableGrossWeight = Number(weight3(item.grossWeight || 0));
  const availableWaxStoneWeight = Number(weight3(safeItemWaxStoneWeight(item)));
  const availableNonGoldWeight = Number(weight3(safeItemNonGoldWeight(item)));
  const availableNonGoldBreakdown = safeItemNonGoldBreakdown(item);
  const availableNetWeight = Number(weight3(safeItemGoldWeight(item)));
  const issuedGrossWeight = Number(weight3(form.grossWeight.value || 0));
  const issuedWaxStoneWeight = Number(weight3(form.waxStoneWeight.value || 0));
  const issuedNonGoldBreakdown = safeIssueEnteredNonGoldBreakdown(form);
  const issuedNonGoldWeight = nonGoldBreakdownTotal(issuedNonGoldBreakdown);
  const issuedNetWeight = Number(weight3(Math.max(issuedGrossWeight - issuedWaxStoneWeight - issuedNonGoldWeight, 0)));
  const manuallyEnteredStoneWeight = Number(weight3(issuedNonGoldBreakdown.stone || 0));
  const stoneAdjustmentType = normalizeSafeIssueStoneAdjustmentType(form.stoneAdjustmentType?.value);
  const stoneAdjustmentParts = safeIssueStoneAdjustmentParts(
    stoneAdjustmentType,
    manuallyEnteredStoneWeight,
    form.jobWaxStoneWeight?.value,
    form.jobHandStoneWeight?.value,
  );
  const stoneAdjustmentOrder = linkedOrder || (selection.orders.length === 1 ? selection.orders[0] : null);
  const stoneAdjustmentOrders = stoneAdjustmentOrder ? [stoneAdjustmentOrder] : selection.orders;
  const completedStage = String(form.completedStage?.value || "").trim();
  const completedStages = completedProductionStagesForLots(lot ? [lot] : []);
  if (linksJobCard && completedStages.length && !completedStages.some((stage) => departmentTextKey(stage) === departmentTextKey(completedStage))) {
    alert("Select the last completed production stage for this Job Card issue.");
    return;
  }
  if (linksJobCard && manuallyEnteredStoneWeight > 0 && !stoneAdjustmentType) {
    alert("Select whether the entered Stone should trace the existing Job Card stone or add missing Wax / Hand stone.");
    return;
  }
  if (stoneAdjustmentType && manuallyEnteredStoneWeight <= 0) {
    alert("Enter Stone weight in Non-Gold Components before selecting a Job Card stone adjustment.");
    return;
  }
  if (stoneAdjustmentType === "both" && (stoneAdjustmentParts.wax <= 0 || stoneAdjustmentParts.hand <= 0)) {
    alert("Enter both Wax Stone and Hand Stone portions for the combined adjustment.");
    return;
  }
  if (stoneAdjustmentType && Math.abs(stoneAdjustmentParts.total - manuallyEnteredStoneWeight) > 0.0005) {
    alert(`Stone adjustment does not match. Entered Stone ${gram(manuallyEnteredStoneWeight)} must equal Wax ${gram(stoneAdjustmentParts.wax)} + Hand ${gram(stoneAdjustmentParts.hand)} = ${gram(stoneAdjustmentParts.total)}.`);
    return;
  }
  if (stoneAdjustmentType && stoneAdjustmentType !== "trace" && !stoneAdjustmentOrder) {
    alert("Select one individual Semi-Finished Product / PR when adding missing stone. Trace Existing can use Whole Job Card / All PR Items.");
    return;
  }
  if (form.nonGoldWeightUnknown.checked && nonGoldPickerSelectedTypes(form).length !== 1) {
    alert("Weight Unknown can be used for one selected component only. For a combination, enter each component weight separately.");
    return;
  }
  if (!form.nonGoldWeightUnknown.checked && nonGoldPickerSelectedTypes(form).some((category) => {
    const input = form.querySelector(`[data-non-gold-weight="${category}"]`);
    return Number(input?.value || 0) <= 0;
  })) {
    alert("Enter the weight for every selected non-gold component.");
    return;
  }
  if (issuedGrossWeight <= 0) {
    alert("Enter issue weight greater than zero.");
    return;
  }
  if (issuedWaxStoneWeight < 0 || issuedNonGoldWeight < 0 || issuedWaxStoneWeight + issuedNonGoldWeight > issuedGrossWeight + 0.0005) {
    alert("Wax stone plus non-gold weight cannot be more than issue GW.");
    return;
  }
  if (issuedGrossWeight > availableGrossWeight + 0.0005
    || issuedWaxStoneWeight > availableWaxStoneWeight + 0.0005
    || issuedNonGoldWeight > availableNonGoldWeight + 0.0005
    || !nonGoldBreakdownCanCover(availableNonGoldBreakdown, issuedNonGoldBreakdown, ["combination", "other"])
    || issuedNetWeight > availableNetWeight + 0.0005) {
    alert(`This partial issue exceeds the remaining Safe Locker balance. Remaining: GW ${gram(availableGrossWeight)} / Wax ${gram(availableWaxStoneWeight)} / Non-Gold ${gram(availableNonGoldWeight)} (${nonGoldBreakdownText(availableNonGoldBreakdown) || "none"}) / Gold ${gram(availableNetWeight)}. Enter only the GW and non-gold contained in this small lot; later issues will use the remaining balance.`);
    return;
  }
  const safeGoldIssue = ensureSafeIssueProductionLot({
    selection,
    lot,
    department,
    process: form.process.value,
    item,
    issuedGrossWeight,
    issuedWaxStoneWeight,
    issuedNonGoldWeight,
    issuedNonGoldBreakdown,
    issuedNetWeight,
    stoneAdjustmentParts,
  });
  lot = safeGoldIssue.lot;
  const lotMovedToDepartment = !safeGoldIssue.created && destinationMode === "both"
    ? transferExistingLotForSafeIssue(lot, department, form.process.value, item)
    : false;
  const issue = createSafeDepartmentIssue(item, department, form.process.value, form.remarks.value, {
    grossWeight: issuedGrossWeight,
    waxStoneWeight: issuedWaxStoneWeight,
    nonGoldWeight: issuedNonGoldWeight,
    nonGoldCategory: nonGoldBreakdownCategory(issuedNonGoldBreakdown),
    nonGoldBreakdown: issuedNonGoldBreakdown,
    nonGoldWeightKnown: !form.nonGoldWeightUnknown.checked,
    netWeight: issuedNetWeight,
    destinationMode,
    lotId: lot?.id || "",
    lotNumber: lot?.number || "",
    jobNumber: selection.jobNumber || "",
    orderId: linkedOrder?.id || "",
    productionNo: linkedOrder?.productionNo || linkedOrder?.number || "",
    designNumber: linkedOrder?.designNumber || designLabel(linkedOrder?.designId) || "",
    itemName: linkedOrder?.item || linkedOrder?.category || "",
    stoneAdjustmentType,
    stoneAdjustmentWeight: stoneAdjustmentType ? manuallyEnteredStoneWeight : 0,
    waxStoneAdjustmentWeight: stoneAdjustmentParts.wax,
    handStoneAdjustmentWeight: stoneAdjustmentParts.hand,
    stoneAdjustmentOrderId: stoneAdjustmentOrder?.id || "",
    stoneAdjustmentProductionNo: stoneAdjustmentOrder?.productionNo || stoneAdjustmentOrder?.number || (stoneAdjustmentType === "trace" ? "Whole Job Card" : ""),
    completedStage,
    goldIssueLotId: safeGoldIssue.created ? lot?.id || "" : "",
  });
  state.safeDepartmentIssues = state.safeDepartmentIssues || [];
  state.safeDepartmentIssues.unshift(issue);
  if (safeGoldIssue.created && lot) lot.safeDepartmentIssueId = issue.id;
  syncProductionReturnAfterSafeIssue(item, issue, lot);
  const stoneAdjustmentSummary = applySafeIssueStoneAdjustment(stoneAdjustmentOrder, issue, stoneAdjustmentOrders);
  const remainingGrossWeight = Number(weight3(Math.max(availableGrossWeight - issuedGrossWeight, 0)));
  const remainingWaxStoneWeight = Number(weight3(Math.max(availableWaxStoneWeight - issuedWaxStoneWeight, 0)));
  const remainingNonGoldWeight = Number(weight3(Math.max(availableNonGoldWeight - issuedNonGoldWeight, 0)));
  const remainingNonGoldBreakdown = subtractNonGoldBreakdown(availableNonGoldBreakdown, issuedNonGoldBreakdown, ["combination", "other"]);
  const remainingNetWeight = safeItemNetFromGross(remainingGrossWeight, remainingWaxStoneWeight, remainingNonGoldWeight);
  if (remainingGrossWeight <= 0.0005 && remainingNetWeight <= 0.0005) {
    item.status = "Out";
    item.outDate = today();
    item.issueDepartmentId = department.id;
    item.issueDepartmentName = department.name;
    item.issueProcess = issue.process;
    item.safeDepartmentIssueId = issue.id;
    item.issueDestinationMode = issue.destinationMode;
    item.issueLotId = issue.lotId;
    item.issueLotNumber = issue.lotNumber;
    item.issueJobNumber = issue.jobNumber;
    item.issueOrderId = issue.orderId;
    item.issueProductionNo = issue.productionNo;
  } else {
    item.grossWeight = remainingGrossWeight;
    item.waxStoneWeight = remainingWaxStoneWeight;
    item.nonGoldWeight = remainingNonGoldWeight;
    item.nonGoldBreakdown = remainingNonGoldBreakdown;
    item.nonGoldCategory = remainingNonGoldWeight > 0
      ? nonGoldBreakdownCategory(remainingNonGoldBreakdown, item.nonGoldCategory || issue.nonGoldCategory)
      : item.nonGoldCategory || "";
    item.nonGoldWeightKnown = item.nonGoldWeightKnown !== false && issue.nonGoldWeightKnown !== false;
    item.netWeight = remainingNetWeight;
  }
  const issueDestination = safeIssueDestinationDescription(issue);
  item.remarks = `${remainingGrossWeight > 0.0005 ? "Part issued" : "Issued"} to ${issueDestination}${issue.remarks ? ` / ${issue.remarks}` : ""}`;
  document.getElementById("safe-issue-dialog").close();
  form.reset();
  saveState();
  render();
  refreshOpenDepartmentTransferHistory();
  const issueWeightSummary = issue.issuedNonGoldWeight > 0
    ? `${nonGoldBreakdownText(issue.issuedNonGoldBreakdown, issue.nonGoldCategory, issue.issuedNonGoldWeight)} / Total ${gram(issue.issuedNonGoldWeight)}`
    : `GW ${gram(issue.issuedGrossWeight)} / Gold ${gram(issue.issuedNetWeight)}`;
  const lotActionSummary = safeGoldIssue.created
    ? `\nGOLD ISSUE CREATED: ${lot.number} / ${lot.currentDepartment || lot.karigarName}.`
    : lotMovedToDepartment
      ? `\nLOT TRANSFERRED: ${lot.number} / ${lot.currentDepartment || lot.karigarName}.`
      : "";
  alert(`${safeIssueDestinationModeLabel(destinationMode)} saved.\n${issue.jobNumber ? `${issue.jobNumber}${issue.lotNumber ? ` / ${issue.lotNumber}` : " / Gold Pending"}${issue.productionNo ? ` / ${issue.productionNo}` : ""}\n` : ""}${issueWeightSummary} issued to ${department.name}.${lotActionSummary}${stoneAdjustmentSummary ? `\n${stoneAdjustmentSummary}` : ""}`);
});

