function getFormData(form) {
  return Object.fromEntries(new FormData(form).entries());
}

function uploadErrorText(error) {
  const message = String(error?.message || error?.error_description || error?.details || error?.name || error || "Unknown error").trim();
  if (/quota|storage|space|full|exceed|maximum|memory/i.test(message)) {
    return "Browser storage is full or the selected image is too large.";
  }
  if (/bucket|design-images|row-level|permission|unauthor/i.test(message)) {
    return "Supabase design image storage is not ready or permission is missing.";
  }
  return message;
}

function waitForUiPaint() {
  return new Promise((resolve) => {
    requestAnimationFrame(() => setTimeout(resolve, 0));
  });
}

async function runPreviewBatch(items = [], worker, batchSize = IMAGE_PREVIEW_BATCH_SIZE) {
  const list = [...items];
  let cursor = 0;
  const runners = Array.from({ length: Math.min(batchSize, list.length) }, async () => {
    while (cursor < list.length) {
      const item = list[cursor];
      cursor += 1;
      await worker(item);
    }
  });
  await Promise.all(runners);
}

function duplicateActionProgressText(action = "") {
  const choice = cleanDuplicateDesignAction(action);
  if (choice === "REPLACE") return "Replacing duplicate";
  if (choice === "MERGE") return "Merging duplicate";
  if (choice === "NEW") return "Creating copy";
  return "Skipping duplicate";
}

function duplicateActionProgressDoneText(action = "") {
  const choice = cleanDuplicateDesignAction(action);
  if (choice === "REPLACE") return "replaced";
  if (choice === "MERGE") return "merged";
  if (choice === "NEW") return "created copy for";
  return "skipped";
}

function calculateDueDate(orderDate, productionDays) {
  if (!orderDate) return "";
  const date = new Date(`${orderDate}T00:00:00`);
  date.setDate(date.getDate() + normalizeProductionDays(productionDays));
  return date.toISOString().slice(0, 10);
}

function normalizeProductionDays(value) {
  const days = Math.floor(Number(value));
  if (!Number.isFinite(days)) return MIN_PRODUCTION_DAYS;
  return Math.max(MIN_PRODUCTION_DAYS, days);
}

function productionDaysValidationMessage(value, required = false) {
  const rawValue = String(value ?? "").trim();
  if (!rawValue) return required ? "Enter production days." : "";
  const days = Number(rawValue);
  if (!Number.isFinite(days)) return "Enter valid production days.";
  if (!Number.isInteger(days)) return "Production days must be a whole number.";
  if (days < MIN_PRODUCTION_DAYS) return PRODUCTION_DAYS_MIN_ERROR;
  return "";
}

function setProductionDaysError(form, message = "") {
  if (!form?.productionDays) return;
  form.productionDays.setCustomValidity(message);
  form.productionDays.closest("label")?.classList.toggle("field-invalid", Boolean(message));
  const errorNode = form.querySelector("[data-production-days-error]");
  if (errorNode) {
    errorNode.textContent = message;
    errorNode.classList.toggle("hidden", !message);
  }
}

function daysBetween(startDate, endDate) {
  if (!startDate || !endDate) return 0;
  const start = new Date(`${startDate}T00:00:00`);
  const end = new Date(`${endDate}T00:00:00`);
  return Math.max(Math.round((end - start) / 86400000), 0);
}

function updateOrderDueDate(form, required = false) {
  const message = productionDaysValidationMessage(form.productionDays.value, required);
  setProductionDaysError(form, message);
  if (message || !form.productionDays.value) {
    form.dueDate.value = "";
    return false;
  }
  const productionDays = Number(form.productionDays.value);
  form.dueDate.value = calculateDueDate(form.orderDate.value, productionDays);
  return true;
}

function validateOrderDueDate(form) {
  const isValid = updateOrderDueDate(form, true);
  if (!isValid) {
    form.productionDays.reportValidity?.();
    form.productionDays.focus();
  }
  return isValid;
}

function setDefaultOrderDates(form) {
  if (!form.orderDate.value) form.orderDate.value = isoToday();
  if (!form.productionDays.value) form.productionDays.value = MIN_PRODUCTION_DAYS;
  if (form.jobColor && !form.jobColor.value) form.jobColor.value = "Pink";
  updateOrderDueDate(form);
}

