function startJobPrint(html, mode = "job") {
  if (typeof activeJobPrintCleanup === "function") activeJobPrintCleanup();
  const printArea = getGlobalPrintArea();
  printArea.innerHTML = html;
  setPrintPageSize(mode);
  const mobilePrint = requiresDirectTapForPrint();
  let cleaned = false;
  let closeMobilePrompt = null;
  let restoreMobilePage = null;
  let mobilePrintReturnTimer = null;
  let mobilePrintLeftPage = false;
  const handleMobilePrintLeave = () => {
    mobilePrintLeftPage = true;
  };
  const handleMobilePrintReturn = () => {
    if (!mobilePrintLeftPage || cleaned) return;
    window.clearTimeout(mobilePrintReturnTimer);
    mobilePrintReturnTimer = window.setTimeout(cleanup, 250);
  };
  const handleMobilePrintVisibility = () => {
    if (document.visibilityState === "hidden") handleMobilePrintLeave();
    else handleMobilePrintReturn();
  };
  const cleanup = () => {
    if (cleaned) return;
    cleaned = true;
    window.clearTimeout(mobilePrintReturnTimer);
    closeMobilePrompt?.();
    document.body.classList.remove("printing-order");
    document.body.classList.remove("printing-single-item");
    document.body.classList.remove("printing-transfer-bag");
    restoreMobilePage?.();
    printArea.innerHTML = "";
    setPrintPageSize("job");
    window.removeEventListener("afterprint", cleanup);
    window.removeEventListener("blur", handleMobilePrintLeave);
    window.removeEventListener("focus", handleMobilePrintReturn);
    document.removeEventListener("visibilitychange", handleMobilePrintVisibility);
    if (activeJobPrintCleanup === cleanup) activeJobPrintCleanup = null;
  };
  const printNow = () => {
    if (cleaned) return;
    document.body.classList.add("printing-order");
    document.body.classList.toggle("printing-single-item", mode === "single");
    document.body.classList.toggle("printing-transfer-bag", mode === "transfer-bag");
    if (mobilePrint) {
      restoreMobilePage = isolateJobBagForMobilePrint(printArea, mode);
      window.addEventListener("blur", handleMobilePrintLeave);
      window.addEventListener("focus", handleMobilePrintReturn);
      document.addEventListener("visibilitychange", handleMobilePrintVisibility);
    }
    printArea.getBoundingClientRect();
    prepareJobPrintLayout(document, mode);
    try {
      window.print();
    } catch (error) {
      cleanup();
      alert(`Print could not open: ${error.message}`);
    }
  };
  activeJobPrintCleanup = cleanup;
  window.addEventListener("afterprint", cleanup);
  if (mobilePrint) {
    const openPrintOnlyPage = () => {
      if (openMobileJobPrintWindow(html, mode)) cleanup();
      else printNow();
    };
    closeMobilePrompt = showMobileJobPrintPrompt(mode, openPrintOnlyPage, cleanup);
    return;
  }
  document.body.classList.add("printing-order");
  document.body.classList.toggle("printing-single-item", mode === "single");
  document.body.classList.toggle("printing-transfer-bag", mode === "transfer-bag");
  setTimeout(() => {
    if (!cleaned) {
      prepareJobPrintLayout(document, mode);
      window.print();
    }
  }, 100);
}

function openMobileJobPrintWindow(html, mode = "job") {
  const printWindow = window.open("", "_blank");
  if (!printWindow) return false;
  const styleUrl = new URL(`styles.css?v=${APP_BUILD}`, window.location.href).href;
  const pageClass = mode === "single"
    ? "printing-order printing-single-item"
    : mode === "transfer-bag"
      ? "printing-order printing-transfer-bag"
      : "printing-order";
  const paperWidth = mode === "job" ? "210mm" : "105mm";
  const layoutLabel = jobPrintModeLabel(mode);
  try {
    printWindow.document.open();
    printWindow.document.write(`<!doctype html>
      <html lang="en">
        <head>
          <meta charset="utf-8">
          <meta name="viewport" content="width=device-width, initial-scale=1">
          <title>Job Bag Print - ${escapeHtml(layoutLabel)}</title>
          <link rel="stylesheet" href="${escapeHtml(styleUrl)}">
          <style>
            html, body { margin: 0 !important; min-height: 100%; background: #eef4f1 !important; }
            body.mobile-job-print-page { display: block !important; width: auto !important; overflow: auto !important; }
            .mobile-print-page-toolbar { position: sticky; top: 0; z-index: 100; display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 12px 16px; background: #ffffff; border-bottom: 1px solid #cbded8; box-shadow: 0 8px 24px rgba(7, 50, 43, 0.14); font-family: Arial, sans-serif; }
            .mobile-print-page-toolbar div { display: grid; gap: 2px; }
            .mobile-print-page-toolbar strong { color: #123e37; font-size: 16px; }
            .mobile-print-page-toolbar small { color: #587269; font-size: 11px; }
            .mobile-print-page-actions { display: flex; gap: 8px; }
            .mobile-print-page-actions button { min-height: 42px; padding: 8px 14px; border: 1px solid #0f766e; border-radius: 7px; background: #0f766e; color: #ffffff; font: 800 13px Arial, sans-serif; }
            .mobile-print-page-actions button.ghost { background: #ffffff; color: #0f5d55; }
            .mobile-print-page-actions button:disabled { cursor: wait; opacity: 0.6; }
            body.mobile-job-print-page .global-print-area { display: block !important; position: static !important; width: ${paperWidth} !important; margin: 14px auto !important; overflow: visible !important; background: #ffffff !important; }
            @media (max-width: 620px) {
              .mobile-print-page-toolbar { align-items: stretch; flex-direction: column; }
              .mobile-print-page-actions { display: grid; grid-template-columns: 1fr 1fr; }
              .mobile-print-page-actions button { width: 100%; }
            }
            @media print {
              .mobile-print-page-toolbar { display: none !important; }
              body.mobile-job-print-page .global-print-area { margin: 0 !important; }
            }
          </style>
        </head>
        <body class="mobile-job-print-page ${pageClass}">
          <header class="mobile-print-page-toolbar" id="mobile-print-page-toolbar">
            <div>
              <strong>Job Bag Print</strong>
              <small>${escapeHtml(layoutLabel)} / Only the bag below will print</small>
            </div>
            <div class="mobile-print-page-actions">
              <button class="ghost" type="button" id="mobile-print-page-close">Close</button>
              <button type="button" id="mobile-print-page-print" disabled>Preparing Bag...</button>
            </div>
          </header>
          <section id="global-print-area" class="order-print-area global-print-area">${html}</section>
        </body>
      </html>`);
    printWindow.document.close();
  } catch (error) {
    printWindow.close();
    return false;
  }
  const enablePrint = () => {
    const printButton = printWindow.document.getElementById("mobile-print-page-print");
    if (!printButton) return;
    printButton.disabled = false;
    printButton.textContent = "Print / Save PDF";
  };
  const handlePrint = () => {
    const toolbar = printWindow.document.getElementById("mobile-print-page-toolbar");
    const printArea = printWindow.document.getElementById("global-print-area");
    toolbar?.remove();
    printArea?.getBoundingClientRect();
    prepareJobPrintLayout(printWindow.document, mode);
    printWindow.focus();
    printWindow.print();
  };
  const bindPrintPage = () => {
    const printButton = printWindow.document.getElementById("mobile-print-page-print");
    const closeButton = printWindow.document.getElementById("mobile-print-page-close");
    printButton?.addEventListener("click", handlePrint);
    closeButton?.addEventListener("click", () => printWindow.close());
    const images = Array.from(printWindow.document.images || []);
    const imageReady = images.map((image) => image.complete
      ? Promise.resolve()
      : new Promise((resolve) => {
        image.addEventListener("load", resolve, { once: true });
        image.addEventListener("error", resolve, { once: true });
      }));
    Promise.all(imageReady).then(() => {
      prepareJobPrintLayout(printWindow.document, mode);
      enablePrint();
    });
    printWindow.setTimeout(() => {
      prepareJobPrintLayout(printWindow.document, mode);
      enablePrint();
    }, 3000);
  };
  if (printWindow.document.readyState === "complete") bindPrintPage();
  else printWindow.addEventListener("load", bindPrintPage, { once: true });
  return true;
}

function isolateJobBagForMobilePrint(printArea, mode = "job") {
  const body = document.body;
  const bodyStyle = body.getAttribute("style");
  const printAreaStyle = printArea.getAttribute("style");
  const detachedPage = document.createDocumentFragment();
  Array.from(body.childNodes).forEach((node) => {
    if (node !== printArea) detachedPage.appendChild(node);
  });
  const paperWidth = mode === "job" ? "210mm" : "105mm";
  body.classList.add("mobile-print-isolated");
  body.style.setProperty("display", "block", "important");
  body.style.setProperty("width", paperWidth, "important");
  body.style.setProperty("margin", "0", "important");
  body.style.setProperty("overflow", "visible", "important");
  body.style.setProperty("background", "#ffffff", "important");
  printArea.style.setProperty("display", "block", "important");
  printArea.style.setProperty("position", "static", "important");
  printArea.style.setProperty("width", paperWidth, "important");
  printArea.style.setProperty("overflow", "visible", "important");
  printArea.getBoundingClientRect();
  let restored = false;
  return () => {
    if (restored) return;
    restored = true;
    body.insertBefore(detachedPage, printArea);
    body.classList.remove("mobile-print-isolated");
    if (bodyStyle === null) body.removeAttribute("style");
    else body.setAttribute("style", bodyStyle);
    if (printAreaStyle === null) printArea.removeAttribute("style");
    else printArea.setAttribute("style", printAreaStyle);
  };
}

function requiresDirectTapForPrint() {
  const userAgent = navigator.userAgent || "";
  const mobileBrowser = /Android|iPad|iPhone|iPod|Mobile/i.test(userAgent);
  const coarsePointer = window.matchMedia?.("(pointer: coarse)")?.matches;
  return Boolean(mobileBrowser || coarsePointer || navigator.maxTouchPoints > 1);
}

function jobPrintModeLabel(mode = "job") {
  if (mode === "single") return "A6 / 1 Job Bag Per Page";
  if (mode === "transfer-bag") return "A6 / Complete Item List + Transfer History";
  return "A4 / 4 Job Bags Per Page";
}

function showMobileJobPrintPrompt(mode, onPrint, onCancel) {
  const dialog = document.getElementById("mobile-print-dialog");
  const printButton = document.getElementById("mobile-print-now");
  const cancelButton = document.getElementById("mobile-print-cancel");
  const format = document.getElementById("mobile-print-format");
  if (!dialog || !printButton || !cancelButton) {
    onPrint();
    return () => {};
  }
  if (format) format.textContent = `${jobPrintModeLabel(mode)} / Opens In A Print-Only Page`;
  let settled = false;
  const detach = () => {
    printButton.removeEventListener("click", handlePrint);
    cancelButton.removeEventListener("click", handleCancel);
    dialog.removeEventListener("cancel", handleDialogCancel);
    dialog.removeEventListener("close", handleDialogClose);
  };
  const closeDialog = () => {
    if (dialog.open) dialog.close();
  };
  const handlePrint = () => {
    if (settled) return;
    settled = true;
    detach();
    closeDialog();
    onPrint();
  };
  const handleCancel = () => {
    if (settled) return;
    settled = true;
    detach();
    closeDialog();
    onCancel();
  };
  const handleDialogCancel = (event) => {
    event.preventDefault();
    handleCancel();
  };
  const handleDialogClose = () => {
    if (!settled) handleCancel();
  };
  printButton.addEventListener("click", handlePrint);
  cancelButton.addEventListener("click", handleCancel);
  dialog.addEventListener("cancel", handleDialogCancel);
  dialog.addEventListener("close", handleDialogClose);
  if (!dialog.open) dialog.showModal();
  requestAnimationFrame(() => printButton.focus());
  return () => {
    if (settled) return;
    settled = true;
    detach();
    closeDialog();
  };
}

function setPrintPageSize(mode = "job") {
  let style = document.getElementById("dynamic-print-page-size");
  if (!style) {
    style = document.createElement("style");
    style.id = "dynamic-print-page-size";
    document.head.appendChild(style);
  }
  if (mode === "bill") {
    style.textContent = "@media print { @page { size: A6 landscape; margin: 0; } html, body { width: 148.5mm !important; height: 105mm !important; margin: 0 !important; padding: 0 !important; } }";
  } else if (mode === "packing-list") {
    style.textContent = "@media print { @page { size: 297mm 210mm; margin: 0; } }";
  } else if (mode === "hallmark-tags") {
    style.textContent = "@media print { @page { size: 210mm 297mm; margin: 0; } html, body { margin: 0 !important; padding: 0 !important; } }";
  } else if (mode === "bill-tags-a6") {
    style.textContent = "@media print { @page { size: 105mm 151.75mm; margin: 0; } html, body { margin: 0 !important; padding: 0 !important; } }";
  } else if (mode === "barcode") {
    style.textContent = "@media print { @page { size: A4 portrait; margin: 10mm; } }";
  } else if (mode === "catalogue") {
    style.textContent = "@media print { @page { size: A4 portrait; margin: 8mm; } }";
  } else if (mode === "single" || mode === "transfer-bag") {
    style.textContent = "@media print { @page { size: 105mm 148.5mm; margin: 0; } }";
  } else {
    style.textContent = "@media print { @page { size: A4 portrait; margin: 0; } }";
  }
}

function getGlobalPrintArea() {
  let printArea = document.getElementById("global-print-area");
  if (!printArea) {
    printArea = document.createElement("section");
    printArea.id = "global-print-area";
    printArea.className = "order-print-area global-print-area";
    document.body.appendChild(printArea);
  }
  return printArea;
}

