function printBill(lotId, billOverride = null) {
  const lot = findById("lots", lotId);
  if (!lot) return;
  const bill = billOverride || lot.bill || state.bills?.find((item) => item.lotId === lot.id);
  if (!bill?.id) {
    alert("Generate bill first, then print.");
    return;
  }
  if (!billHasFinalQcOkItems(bill)) {
    alert("Only QC OK items transferred to Office can be printed in the final bill.");
    return;
  }
  startBillPrint(billPrintHtml(lot, bill), { onePage: true });
}

function printPackingList(lotId, billOverride = null) {
  const lot = findById("lots", lotId);
  if (!lot) return;
  const bill = billOverride || lot.bill || state.bills?.find((item) => item.lotId === lot.id);
  if (!bill?.id) {
    alert("Generate bill first, then print packing list.");
    return;
  }
  if (!billHasFinalQcOkItems(bill)) {
    alert("Only QC OK items transferred to Office can be printed in the packing list.");
    return;
  }
  startPackingListPrint(packingListPrintHtml(lot, bill));
}

function printBillTags(lotId, billOverride = null, pageSize = "a4") {
  const lot = findById("lots", lotId);
  if (!lot) return;
  const bill = billOverride || lot.bill || state.bills?.find((item) => item.lotId === lot.id);
  if (!bill?.id) {
    alert("Generate bill first, then print tags.");
    return;
  }
  if (!billHasFinalQcOkItems(bill)) {
    alert("Only QC OK items transferred to Office can be printed as tags.");
    return;
  }
  const normalizedPageSize = pageSize === "a6" ? "a6" : "a4";
  startHallmarkTagPrint(billTagsPrintHtml(lot, bill, normalizedPageSize), null, { pageSize: normalizedPageSize });
}

