    const savedNonGoldCategory = normalizeSafeNonGoldCategory(item.nonGoldCategory || item.materialType || (savedSafeKind === "non-gold" ? "other" : ""));
    const nonGoldWeightKnown = item.nonGoldWeightKnown !== undefined
